/**
 * Unit tests for EvidenceCollector
 * Tests integrity validation and redaction functionality
 */

import { test, describe } from 'node:test';
import { strictEqual, ok } from 'node:assert';
import { readFile, stat } from 'node:fs/promises';
import { join } from 'node:path';
import { EvidenceCollector } from '../../src/core/EvidenceCollector.js';
import { createTestEnvironment, MockRepositoryAdapter } from '../setup.js';

describe('EvidenceCollector', () => {
  test('stores evidence with proper integrity validation', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const testData = {
      test_id: 'integrity-test',
      status: 'Passed',
      output: 'Test completed successfully',
      metadata: { duration: 1000 }
    };

    try {
      const evidencePath = await collector.storeEvidence('test-evidence-1', testData);

      ok(evidencePath, 'Should return evidence path');
      ok(evidencePath.includes('test-evidence-1'), 'Evidence path should include original ID');

      // Verify evidence file was created
      const manifest = await collector.generateManifest();
      ok(manifest.some(e => e.evidence_id === 'test-evidence-1'), 'Evidence file should exist');

    } finally {
      await env.cleanup();
    }
  });

  test('generates checksums for evidence integrity', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const testData = { content: 'test data for checksum' };

    try {
      await collector.storeEvidence('checksum-test', testData);

      const manifest = await collector.generateManifest();
      const evidenceEntry = manifest.find(e => e.evidence_id === 'checksum-test');

      ok(evidenceEntry, 'Should find evidence in manifest');
      ok(evidenceEntry.checksum, 'Should have checksum');
      strictEqual(evidenceEntry.checksum.length, 64, 'Should be SHA-256 hash (64 chars)');
      ok(evidenceEntry.file_size > 0, 'Should record file size');

    } finally {
      await env.cleanup();
    }
  });

  test('redacts sensitive data from evidence', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const sensitiveData = {
      command: 'deploy --api-key=secret123',
      env_vars: {
        DATABASE_PASSWORD: 'password123',
        API_TOKEN: 'token-abc-123',
        SAFE_VALUE: 'public-info'
      },
      output: 'Connected with password: secret123'
    };

    try {
      await collector.storeEvidence('redaction-test', sensitiveData);

      const manifest = await collector.generateManifest();
      const evidenceEntry = manifest.find(e => e.evidence_id === 'redaction-test');
      ok(evidenceEntry, 'Should find evidence');

      // Read the actual evidence file to verify redaction
      const evidenceFilePath = join(env.evidenceDir, evidenceEntry.file_path);
      const evidenceContent = await readFile(evidenceFilePath, 'utf8');
      const parsedEvidence = JSON.parse(evidenceContent);

      // Verify sensitive values are redacted
      ok(parsedEvidence.data.command.includes('[REDACTED]'), 'API key should be redacted');
      strictEqual(parsedEvidence.data.env_vars.DATABASE_PASSWORD, '[REDACTED]', 'Password should be redacted');
      strictEqual(parsedEvidence.data.env_vars.API_TOKEN, '[REDACTED]', 'Token should be redacted');
      strictEqual(parsedEvidence.data.env_vars.SAFE_VALUE, 'public-info', 'Safe values should not be redacted');
      ok(parsedEvidence.data.output.includes('[REDACTED]'), 'Output password should be redacted');

    } finally {
      await env.cleanup();
    }
  });

  test('stores execution traces with proper metadata', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const traceData = {
      command: 'npm test',
      exitCode: 0,
      stdout: 'All tests passed',
      stderr: '',
      startedAt: new Date().toISOString(),
      endedAt: new Date().toISOString()
    };

    try {
      const traceId = await collector.storeExecutionTrace(
        traceData.command,
        traceData.exitCode,
        traceData.stdout,
        traceData.stderr,
        traceData.startedAt,
        traceData.endedAt
      );

      ok(traceId, 'Should return trace ID');
      ok(traceId.includes('execution_trace'), 'Trace ID should indicate type');

      const manifest = await collector.generateManifest();
      const traceEntry = manifest.find(e => e.evidence_id === traceId);

      ok(traceEntry, 'Should find trace in manifest');
      strictEqual(traceEntry.evidence_type, 'execution_trace', 'Should classify as execution trace');

    } finally {
      await env.cleanup();
    }
  });

  test('validates evidence integrity after storage', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const testData = { validation: 'test data' };

    try {
      const evidencePath = await collector.storeEvidence('validation-test', testData);

      // Generate manifest to trigger integrity validation
      const manifest = await collector.generateManifest();
      const entry = manifest.find(e => e.evidence_id === 'validation-test');

      ok(entry, 'Evidence should be in manifest');
      ok(entry.integrity_validated, 'Evidence should be marked as integrity validated');

      // Verify file actually exists and matches size
      const filePath = join(env.evidenceDir, entry.file_path);
      const stats = await stat(filePath);
      strictEqual(stats.size, entry.file_size, 'File size should match manifest');

    } finally {
      await env.cleanup();
    }
  });

  test('handles concurrent evidence storage safely', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const concurrentOperations = Array.from({ length: 5 }, (_, i) => 
      collector.storeEvidence(`concurrent-test-${i}`, { index: i, data: `test data ${i}` })
    );

    try {
      const evidenceIds = await Promise.all(concurrentOperations);

      strictEqual(evidenceIds.length, 5, 'Should store all evidence items');

      // Verify all evidence IDs are unique
      const uniqueIds = new Set(evidenceIds);
      strictEqual(uniqueIds.size, 5, 'All evidence IDs should be unique');

      // Verify all files exist
      const manifest = await collector.generateManifest();
      strictEqual(manifest.length, 5, 'Manifest should contain all evidence items');

    } finally {
      await env.cleanup();
    }
  });

  test('classifies evidence types correctly', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const collector = new EvidenceCollector(adapter, env.evidenceDir);

    const testCases = [
      {
        id: 'execution_trace_123',
        data: { command: 'test', exitCode: 0 },
        expectedType: 'execution_trace'
      },
      {
        id: 'preflight_check_result',
        data: { command: 'typecheck', exit_code: 0 },
        expectedType: 'command_execution'
      },
      {
        id: 'configuration_data',
        data: { config: 'value' },
        expectedType: 'configuration'
      },
      {
        id: 'general_evidence',
        data: { info: 'general' },
        expectedType: 'general'
      }
    ];

    try {
      for (const testCase of testCases) {
        await collector.storeEvidence(testCase.id, testCase.data);
      }

      const manifest = await collector.generateManifest();

      for (const testCase of testCases) {
        const entry = manifest.find(e => e.evidence_id.includes(testCase.id));
        ok(entry, `Should find evidence for ${testCase.id}`);
        strictEqual(entry.evidence_type, testCase.expectedType, 
          `${testCase.id} should be classified as ${testCase.expectedType}`);
      }

    } finally {
      await env.cleanup();
    }
  });

  test('creates evidence directory if it does not exist', async () => {
    const env = await createTestEnvironment();
    const adapter = new MockRepositoryAdapter();
    const nonExistentDir = join(env.tempDir, 'non-existent', 'evidence');

    // Collector should create the directory
    const collector = new EvidenceCollector(adapter, nonExistentDir);

    try {
      await collector.storeEvidence('directory-test', { test: 'data' });

      // Verify directory was created and evidence stored
      const stats = await stat(nonExistentDir);
      ok(stats.isDirectory(), 'Evidence directory should be created');

      const manifest = await collector.generateManifest();
      ok(manifest.length > 0, 'Should store evidence in new directory');

    } finally {
      await env.cleanup();
    }
  });
});

import { createHash } from 'node:crypto';
import { mkdir, writeFile, readFile, stat } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { randomUUID } from 'node:crypto';
import { createLogger } from '../utils/logger.js';
import type { RepositoryAdapter } from '../types/index.js';

export class EvidenceCollectorError extends Error {
  constructor(message: string, public readonly evidenceId?: string, public readonly cause?: unknown) {
    super(message);
    this.name = 'EvidenceCollectorError';
  }
}

/**
 * EvidenceCollector implements evidence collection with integrity validation
 * according to the specification's evidence policy.
 * 
 * MUST preserve execution evidence with checksums, timestamps, and redaction.
 */
export class EvidenceCollector {
  private readonly logger = createLogger('EvidenceCollector');
  private readonly evidenceStore = new Map<string, any>();

  constructor(
    private readonly adapter: RepositoryAdapter,
    private readonly evidenceRoot: string
  ) {
    this.logger.info({ evidenceRoot }, 'Evidence collector initialized');
    // Ensure evidence directory exists
    this.ensureEvidenceDirectory().catch(error => {
      this.logger.warn({ error, evidenceRoot }, 'Could not create evidence directory during initialization');
    });
  }

  /**
   * Store evidence with integrity validation
   */
  async storeEvidence(evidenceId: string, data: any): Promise<string> {
    try {
      // Ensure evidence directory exists
      await this.ensureEvidenceDirectory();

      // Redact sensitive data
      const redactedData = this.redactSensitiveData(data);

      // Generate evidence record
      const evidenceRecord = {
        evidence_id: evidenceId,
        timestamp: new Date().toISOString(),
        data: redactedData,
        original_size: JSON.stringify(data).length,
        redacted_size: JSON.stringify(redactedData).length,
        redaction_applied: JSON.stringify(data) !== JSON.stringify(redactedData)
      };

      // Calculate checksum
      const checksum = this.calculateChecksum(evidenceRecord);
      (evidenceRecord as any).checksum = checksum;

      // Store in memory for quick access
      this.evidenceStore.set(evidenceId, evidenceRecord);

      // Write to disk for persistence
      const evidencePath = join(this.evidenceRoot, `${evidenceId}.json`);
      await this.writeEvidenceFile(evidencePath, evidenceRecord);

      this.logger.debug({ 
        evidenceId, 
        path: evidencePath, 
        checksum,
        redacted: evidenceRecord.redaction_applied 
      }, 'Evidence stored');

      return evidencePath;

    } catch (error) {
      this.logger.error({ error, evidenceId }, 'Failed to store evidence');
      throw new EvidenceCollectorError(`Evidence storage failed for ${evidenceId}`, evidenceId, error);
    }
  }

  /**
   * Store execution trace evidence
   */
  async storeExecutionTrace(
    command: string, 
    workingDirectory: string, 
    exitCode: number,
    stdout: string,
    stderr: string,
    duration: number,
    startedAt: string,
    endedAt: string
  ): Promise<string> {
    const traceId = `execution_trace_${randomUUID()}`;

    const trace = {
      command,
      working_directory: workingDirectory,
      exit_code: exitCode,
      stdout: this.truncateOutput(stdout, 10000), // Limit output size
      stderr: this.truncateOutput(stderr, 10000),
      duration_ms: duration,
      started_at: startedAt,
      ended_at: endedAt,
      environment_variables: this.getRelevantEnvVars(),
      process_id: process.pid,
      node_version: process.version
    };

    await this.storeEvidence(traceId, trace);
    return traceId;
  }

  /**
   * Store command output separately for large outputs
   */
  async storeCommandOutput(
    commandId: string,
    stdout: string,
    stderr: string
  ): Promise<{ stdoutPath: string; stderrPath: string }> {
    const stdoutId = `${commandId}_stdout`;
    const stderrId = `${commandId}_stderr`;

    const stdoutPath = await this.storeEvidence(stdoutId, {
      type: 'stdout',
      command_id: commandId,
      content: stdout,
      length: stdout.length
    });

    const stderrPath = await this.storeEvidence(stderrId, {
      type: 'stderr',
      command_id: commandId,
      content: stderr,
      length: stderr.length
    });

    return { stdoutPath, stderrPath };
  }

  /**
   * Generate evidence manifest for all collected evidence
   */
  async generateManifest(): Promise<Array<{
    evidence_id: string;
    evidence_type: string;
    file_path: string;
    checksum: string | null;
    file_size: number;
    created_at: string;
    integrity_validated: boolean;
  }>> {
    this.logger.info('Generating evidence manifest');

    const manifest = [];

    for (const [evidenceId, record] of this.evidenceStore.entries()) {
      try {
        const evidencePath = join(this.evidenceRoot, `${evidenceId}.json`);

        // Verify file exists and is accessible
        const fileStats = await stat(evidencePath);
        const availabilityStatus = fileStats.isFile() ? 'available' : 'missing';

        manifest.push({
          evidence_id: evidenceId,
          evidence_type: this.classifyEvidenceType(evidenceId, record.data),
          file_path: `${evidenceId}.json`,
          checksum: record.checksum || null,
          file_size: fileStats.size,
          created_at: record.timestamp,
          integrity_validated: true
        });

      } catch (error) {
        this.logger.warn({ error, evidenceId }, 'Evidence file not accessible');

        manifest.push({
          evidence_id: evidenceId,
          evidence_type: 'unknown',
          file_path: `${evidenceId}.json`,
          checksum: null,
          file_size: 0,
          created_at: new Date().toISOString(),
          integrity_validated: false
        });
      }
    }

    this.logger.info({ totalEvidence: manifest.length }, 'Evidence manifest generated');
    return manifest;
  }

  /**
   * Validate evidence integrity
   */
  async validateEvidenceIntegrity(): Promise<{
    valid: boolean;
    issues: string[];
    totalEvidence: number;
    validEvidence: number;
  }> {
    const issues: string[] = [];
    let validEvidence = 0;

    for (const [evidenceId, record] of this.evidenceStore.entries()) {
      try {
        const evidencePath = join(this.evidenceRoot, `${evidenceId}.json`);

        // Verify file exists
        const fileContent = await readFile(evidencePath, 'utf8');
        const storedRecord = JSON.parse(fileContent);

        // Verify checksum matches
        const currentChecksum = this.calculateChecksum({
          ...storedRecord,
          checksum: undefined // Exclude checksum from checksum calculation
        });

        if (currentChecksum !== storedRecord.checksum) {
          issues.push(`Checksum mismatch for evidence ${evidenceId}`);
        } else {
          validEvidence++;
        }

      } catch (error) {
        issues.push(`Cannot verify evidence ${evidenceId}: ${error}`);
      }
    }

    const valid = issues.length === 0;

    this.logger.info({ 
      valid, 
      issues: issues.length,
      totalEvidence: this.evidenceStore.size,
      validEvidence 
    }, 'Evidence integrity validation completed');

    return {
      valid,
      issues,
      totalEvidence: this.evidenceStore.size,
      validEvidence
    };
  }

  /**
   * Retrieve stored evidence
   */
  async getEvidence(evidenceId: string): Promise<any | null> {
    const record = this.evidenceStore.get(evidenceId);
    if (record) {
      return record.data;
    }

    // Try to load from disk
    try {
      const evidencePath = join(this.evidenceRoot, `${evidenceId}.json`);
      const fileContent = await readFile(evidencePath, 'utf8');
      const storedRecord = JSON.parse(fileContent);

      // Cache in memory
      this.evidenceStore.set(evidenceId, storedRecord);

      return storedRecord.data;
    } catch (error) {
      this.logger.warn({ error, evidenceId }, 'Could not retrieve evidence');
      return null;
    }
  }

  private async ensureEvidenceDirectory(): Promise<void> {
    try {
      await mkdir(this.evidenceRoot, { recursive: true });
    } catch (error) {
      this.logger.error({ error, path: this.evidenceRoot }, 'Failed to create evidence directory');
      throw new EvidenceCollectorError(`Failed to create evidence directory ${this.evidenceRoot}`, undefined, error);
    }
  }

  private async writeEvidenceFile(filePath: string, data: any): Promise<void> {
    await mkdir(dirname(filePath), { recursive: true });
    await writeFile(filePath, JSON.stringify(data, null, 2), 'utf8');
  }

  private calculateChecksum(data: any): string {
    const content = JSON.stringify(data, null, 0); // Consistent serialization
    return createHash('sha256').update(content).digest('hex');
  }

  private redactSensitiveData(data: any): any {
    if (typeof data !== 'object' || data === null) {
      return this.redactSensitiveString(String(data));
    }

    if (Array.isArray(data)) {
      return data.map(item => this.redactSensitiveData(item));
    }

    const redacted = { ...data };

    for (const [key, value] of Object.entries(redacted)) {
      const keyLower = key.toLowerCase();

      // Redact sensitive field names
      if (this.isSensitiveField(keyLower)) {
        redacted[key] = '[REDACTED]';
      } else if (typeof value === 'string') {
        redacted[key] = this.redactSensitiveString(value);
      } else if (typeof value === 'object') {
        redacted[key] = this.redactSensitiveData(value);
      }
    }

    return redacted;
  }

  private isSensitiveField(field: string): boolean {
    const sensitiveFields = [
      'password', 'secret', 'token', 'key', 'auth', 'credential',
      'api_key', 'access_token', 'refresh_token', 'private_key',
      'cert', 'certificate', 'passphrase', 'pin', 'ssn', 'email',
      'phone', 'credit_card', 'bank_account'
    ];

    return sensitiveFields.some(sensitive => field.includes(sensitive));
  }

  private redactSensitiveString(value: string): string {
    // Redact patterns that look like secrets
    const patterns = [
      /\b[A-Za-z0-9+/]{20,}={0,2}\b/g, // Base64-like strings
      /\b[A-Fa-f0-9]{32,}\b/g,         // Hex strings (API keys, hashes)
      /\bsk_[a-zA-Z0-9_]{20,}\b/g,     // Stripe-like secret keys
      /\bpk_[a-zA-Z0-9_]{20,}\b/g,     // Public keys
      /\bghp_[a-zA-Z0-9]{36}\b/g,      // GitHub personal access tokens
      /\bxoxb-[a-zA-Z0-9-]+\b/g,       // Slack bot tokens
      /\bAKIA[0-9A-Z]{16}\b/g,         // AWS access keys
      /\b[A-Za-z0-9+/]{40}\b/g,        // 40-character tokens
      /--api[_-]?key[=:]\s*[^\s]+/gi,  // Command line API key arguments
      /--token[=:]\s*[^\s]+/gi,        // Command line token arguments
      /--password[=:]\s*[^\s]+/gi,     // Command line password arguments
      /password[=:]\s*[^\s]+/gi,       // Generic password patterns in text
    ];

    let redacted = value;
    for (const pattern of patterns) {
      redacted = redacted.replace(pattern, '[REDACTED]');
    }

    return redacted;
  }

  private truncateOutput(output: string, maxLength: number): string {
    if (output.length <= maxLength) {
      return output;
    }

    const truncated = output.substring(0, maxLength);
    return truncated + `\n\n[OUTPUT TRUNCATED - Original length: ${output.length} characters]`;
  }

  private getRelevantEnvVars(): Record<string, string> {
    const relevantVars: Record<string, string> = {};

    // Include important environment variables (non-sensitive)
    const includePatterns = [
      'NODE_ENV', 'CI', 'GITHUB_ACTIONS', 'VERCEL_ENV',
      'PATH', 'HOME', 'USER', 'PWD', 'SHELL'
    ];

    for (const [key, value] of Object.entries(process.env)) {
      if (value && includePatterns.some(pattern => key.includes(pattern))) {
        relevantVars[key] = this.redactSensitiveString(value);
      }
    }

    return relevantVars;
  }

  private classifyEvidenceType(evidenceId: string, data: any): string {
    // Check for execution_trace first since it's a specific type of command execution
    if (evidenceId.includes('execution_trace')) {
      return 'execution_trace';
    }

    // Check data structure for accurate classification
    if (data && typeof data === 'object') {
      if (data.command || data.exit_code !== undefined) {
        return 'command_execution';
      }

      if (data.test_id || data.suite_id) {
        return 'test_result';
      }

      if (data.check_id) {
        return 'preflight_check';
      }
    }

    // Then check other ID patterns

    if (evidenceId.includes('stdout')) {
      return 'command_output_stdout';
    }

    if (evidenceId.includes('stderr')) {
      return 'command_output_stderr';
    }

    if (evidenceId.includes('preflight')) {
      return 'preflight_evidence';
    }

    if (evidenceId.includes('e2e')) {
      return 'e2e_test_evidence';
    }

    if (evidenceId.includes('configuration') || evidenceId.includes('config')) {
      return 'configuration';
    }

    return 'general';
  }
}

/**
 * Test setup and utilities for validation executor tests
 */

import { randomUUID } from 'node:crypto';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import type { ValidationConfig, ExecutionContext, PreflightCheckDefinition, E2ETestDefinition } from '../src/types/index.js';

export interface TestEnvironment {
  tempDir: string;
  evidenceDir: string;
  cleanup: () => Promise<void>;
}

/**
 * Create isolated test environment with temporary directories
 */
export async function createTestEnvironment(): Promise<TestEnvironment> {
  const tempDir = join('/tmp', `validation-test-${randomUUID()}`);
  const evidenceDir = join(tempDir, 'evidence');

  await mkdir(tempDir, { recursive: true });
  await mkdir(evidenceDir, { recursive: true });

  return {
    tempDir,
    evidenceDir,
    cleanup: async () => {
      try {
        await rm(tempDir, { recursive: true, force: true });
      } catch (error) {
        // Ignore cleanup errors in tests
      }
    }
  };
}

/**
 * Create mock validation configuration for testing
 */
export function createMockConfig(overrides: Partial<ValidationConfig> = {}): ValidationConfig {
  return {
    target: 'test-target',
    environment: 'test',
    profile: 'test',
    preflight_commands: ['echo "preflight test"'],
    e2e_commands: ['echo "e2e test"'],
    evidence_root: '/tmp/test-evidence',
    timeout: 5000,
    fail_fast: false,
    skip_patterns: [],
    ...overrides
  };
}

/**
 * Create mock execution context for testing
 */
export function createMockExecutionContext(overrides: Partial<ExecutionContext> = {}): ExecutionContext {
  return {
    target_roots: ['/test/root'],
    source_revision: 'test-commit-123',
    running_revision: null,
    target_environment: 'test',
    environment_type: 'isolated_test',
    active_identity: 'test@example.com',
    preflight_commands: ['npm run typecheck'],
    e2e_commands: ['npm run test:e2e'],
    test_runner: 'node:test',
    test_runner_version: 'v20.0.0',
    configuration_sources: ['package.json', 'tsconfig.json'],
    required_services: ['test-service'],
    target_endpoints: ['http://localhost:3000'],
    required_dependencies: ['typescript', 'node'],
    required_credentials: [],
    evidence_root: '/tmp/test-evidence',
    ...overrides
  };
}

/**
 * Create mock preflight check definitions for testing
 */
export function createMockPreflightChecks(): PreflightCheckDefinition[] {
  return [
    {
      check_id: 'typecheck',
      check_name: 'TypeScript Type Check',
      blocking: true,
      command: 'npm run typecheck',
      working_directory: '/test/root'
    },
    {
      check_id: 'lint',
      check_name: 'ESLint Check',
      blocking: false,
      command: 'npm run lint',
      working_directory: '/test/root'
    }
  ];
}

/**
 * Create mock E2E test definitions for testing
 */
export function createMockE2ETests(): E2ETestDefinition[] {
  return [
    {
      suite_id: 'integration-tests',
      suite_name: 'Integration Test Suite',
      test_id: 'api-test',
      test_name: 'API Integration Test',
      attempt: 1,
      command_or_invocation: 'npm run test:api'
    },
    {
      suite_id: 'e2e-tests',
      suite_name: 'End-to-End Test Suite', 
      test_id: 'user-flow',
      test_name: 'User Flow Test',
      attempt: 1,
      command_or_invocation: 'npm run test:e2e'
    }
  ];
}

/**
 * Mock repository adapter for testing
 */
export class MockRepositoryAdapter {
  private mockPreflightChecks: PreflightCheckDefinition[];
  private mockE2ETests: E2ETestDefinition[];
  private mockExecutionResults: Map<string, { exitCode: number; stdout: string; stderr: string; duration: number }>;

  constructor(
    preflightChecks = createMockPreflightChecks(),
    e2eTests = createMockE2ETests()
  ) {
    this.mockPreflightChecks = preflightChecks;
    this.mockE2ETests = e2eTests;
    this.mockExecutionResults = new Map();
  }

  async resolveExecutionContext(config: ValidationConfig): Promise<ExecutionContext> {
    return createMockExecutionContext({
      evidence_root: config.evidence_root,
      target_environment: config.environment || 'test'
    });
  }

  async discoverPreflightChecks(): Promise<PreflightCheckDefinition[]> {
    return this.mockPreflightChecks;
  }

  async discoverE2ETests(): Promise<E2ETestDefinition[]> {
    return this.mockE2ETests;
  }

  async executeCommand(command: string, workingDir: string): Promise<{
    exitCode: number;
    stdout: string;
    stderr: string;
    duration: number;
  }> {
    const key = `${command}:${workingDir}`;
    const result = this.mockExecutionResults.get(key);

    if (result) {
      return result;
    }

    // Default success response for unknown commands
    return {
      exitCode: 0,
      stdout: `Mock execution of: ${command}`,
      stderr: '',
      duration: 100
    };
  }

  async storeEvidence(evidenceId: string, data: any): Promise<string> {
    return `mock-evidence-${evidenceId}`;
  }

  /**
   * Configure mock command execution results for testing
   */
  setCommandResult(command: string, workingDir: string, result: {
    exitCode: number;
    stdout: string;
    stderr: string;
    duration: number;
  }): void {
    const key = `${command}:${workingDir}`;
    this.mockExecutionResults.set(key, result);
  }
}

/**
 * Assert helpers for validation testing
 */
export const assertions = {
  /**
   * Assert that a validation gate has the expected status
   */
  gateStatus(gate: { status: string }, expectedStatus: string, message?: string): void {
    if (gate.status !== expectedStatus) {
      throw new Error(message || `Expected gate status ${expectedStatus}, got ${gate.status}`);
    }
  },

  /**
   * Assert that evidence references are properly formatted
   */
  evidenceReferences(references: string[], minCount = 1): void {
    if (references.length < minCount) {
      throw new Error(`Expected at least ${minCount} evidence references, got ${references.length}`);
    }

    for (const ref of references) {
      if (typeof ref !== 'string' || ref.length === 0) {
        throw new Error(`Invalid evidence reference: ${ref}`);
      }
    }
  }
};

import pino from 'pino';

/**
 * Create a logger instance for validation executor components
 */
export function createLogger(name: string) {
  return pino({
    name,
    level: process.env.LOG_LEVEL || 'info',
    transport: process.env.NODE_ENV !== 'production' ? {
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'SYS:standard',
        ignore: 'pid,hostname'
      }
    } : undefined
  });
}
